 private static boolean supported(JsonObject task,Set<String> solid){int[] at=p(task.get("p"));if(isAir(s(task,"state",""))||solid.contains(key(at)))return true;for(int[] d:DIRS)if(solid.contains(key(new int[]{at[0]+d[0],at[1]+d[1],at[2]+d[2]})))return true;return false;}
